我来帮你构建一个涵盖八个类别的信息聚合网站。以下是完整的项目实现：

```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>信息聚合中心 - 科技资讯一站通</title>
    <style>
        :root {
            --bg: #0f172a;
            --card-bg: #1e293b;
            --primary: #3b82f6;
            --accent-1: #8b5cf6;
            --accent-2: #06b6d4;
            --accent-3: #10b981;
            --accent-4: #f59e0b;
            --accent-5: #ef4444;
            --accent-6: #ec4899;
            --accent-7: #6366f1;
            --accent-8: #14b8a6;
            --text: #e2e8f0;
            --text-secondary: #94a3b8;
            --border: #334155;
            --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -2px rgba(0, 0, 0, 0.3);
            --radius: 16px;
            --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif;
            background: var(--bg);
            color: var(--text);
            line-height: 1.6;
            min-height: 100vh;
        }

        /* 粒子背景 */
        #particles {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none;
            z-index: 0;
            opacity: 0.4;
        }

        /* 头部 */
        .header {
            position: sticky;
            top: 0;
            z-index: 100;
            background: rgba(15, 23, 42, 0.85);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
            border-bottom: 1px solid var(--border);
            padding: 16px 0;
            transition: all var(--transition);
        }
        .header.scrolled {
            padding: 10px 0;
            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.4);
        }

        .header-inner {
            max-width: 1400px;
            margin: 0 auto;
            padding: 0 24px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            flex-wrap: wrap;
            gap: 12px;
        }
        .logo {
            font-size: 1.5rem;
            font-weight: 800;
            background: linear-gradient(135deg, var(--primary), var(--accent-1));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            white-space: nowrap;
        }
        .header-actions {
            display: flex;
            align-items: center;
            gap: 12px;
            flex-wrap: wrap;
        }
        .refresh-btn {
            background: var(--primary);
            color: #fff;
            border: none;
            padding: 10px 20px;
            border-radius: 25px;
            cursor: pointer;
            font-size: 0.9rem;
            font-weight: 600;
            transition: all var(--transition);
            display: flex;
            align-items: center;
            gap: 6px;
            white-space: nowrap;
        }
        .refresh-btn:hover {
            background: #2563eb;
            transform: translateY(-2px);
            box-shadow: 0 8px 25px rgba(59, 130, 246, 0.4);
        }
        .refresh-btn:active {
            transform: scale(0.95);
        }
        .refresh-btn.spinning .icon {
            animation: spin 0.8s linear infinite;
        }
        @keyframes spin {
            to {
                transform: rotate(360deg);
            }
        }
        .last-updated {
            font-size: 0.8rem;
            color: var(--text-secondary);
            white-space: nowrap;
        }

        /* 分类标签导航 */
        .category-nav {
            max-width: 1400px;
            margin: 0 auto;
            padding: 16px 24px 0;
            display: flex;
            gap: 8px;
            flex-wrap: wrap;
            position: relative;
            z-index: 10;
        }
        .cat-tag {
            padding: 8px 16px;
            border-radius: 20px;
            border: 1px solid var(--border);
            background: transparent;
            color: var(--text-secondary);
            cursor: pointer;
            font-size: 0.85rem;
            font-weight: 500;
            transition: all var(--transition);
            white-space: nowrap;
            user-select: none;
        }
        .cat-tag:hover {
            border-color: var(--primary);
            color: var(--text);
            background: rgba(59, 130, 246, 0.1);
        }
        .cat-tag.active {
            background: var(--primary);
            border-color: var(--primary);
            color: #fff;
            box-shadow: 0 4px 15px rgba(59, 130, 246, 0.3);
        }

        /* 主内容区 */
        .main-container {
            max-width: 1400px;
            margin: 0 auto;
            padding: 20px 24px 40px;
            position: relative;
            z-index: 10;
        }

        .category-section {
            margin-bottom: 32px;
        }
        .category-title {
            font-size: 1.3rem;
            font-weight: 700;
            margin-bottom: 16px;
            display: flex;
            align-items: center;
            gap: 10px;
        }
        .category-title .dot {
            width: 12px;
            height: 12px;
            border-radius: 50%;
            display: inline-block;
            flex-shrink: 0;
        }
        .category-title .count {
            font-size: 0.8rem;
            font-weight: 400;
            color: var(--text-secondary);
            margin-left: auto;
        }

        /* 卡片网格 */
        .card-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
            gap: 16px;
        }
        .card {
            background: var(--card-bg);
            border-radius: var(--radius);
            padding: 20px;
            border: 1px solid var(--border);
            transition: all var(--transition);
            cursor: pointer;
            position: relative;
            overflow: hidden;
            display: flex;
            flex-direction: column;
            gap: 10px;
        }
        .card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 3px;
            background: var(--card-accent, var(--primary));
            transform: scaleX(0);
            transform-origin: left;
            transition: transform var(--transition);
        }
        .card:hover {
            border-color: var(--card-accent, var(--primary));
            transform: translateY(-4px);
            box-shadow: 0 12px 30px rgba(0, 0, 0, 0.5);
        }
        .card:hover::before {
            transform: scaleX(1);
        }
        .card:active {
            transform: scale(0.98);
        }
        .card-source {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: 0.75rem;
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }
        .card-source .source-icon {
            width: 20px;
            height: 20px;
            border-radius: 4px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 0.65rem;
            font-weight: 700;
            color: #fff;
            flex-shrink: 0;
        }
        .card-title {
            font-size: 1.05rem;
            font-weight: 600;
            line-height: 1.4;
            display: -webkit-box;
            -webkit-line-clamp: 3;
            -webkit-box-orient: vertical;
            overflow: hidden;
            color: var(--text);
        }
        .card-title a {
            color: inherit;
            text-decoration: none;
        }
        .card-title a:hover {
            color: var(--primary);
        }
        .card-summary {
            font-size: 0.85rem;
            color: var(--text-secondary);
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
            flex: 1;
        }
        .card-meta {
            display: flex;
            align-items: center;
            gap: 12px;
            font-size: 0.75rem;
            color: var(--text-secondary);
            flex-wrap: wrap;
        }
        .card-meta .tag {
            background: rgba(59, 130, 246, 0.15);
            color: var(--primary);
            padding: 2px 8px;
            border-radius: 10px;
            font-size: 0.7rem;
        }
        .card-external-link {
            display: inline-flex;
            align-items: center;
            gap: 4px;
            font-size: 0.8rem;
            color: var(--primary);
            text-decoration: none;
            font-weight: 500;
            margin-top: auto;
        }
        .card-external-link:hover {
            text-decoration: underline;
        }

        /* 加载状态 */
        .loading-skeleton {
            background: var(--card-bg);
            border-radius: var(--radius);
            padding: 20px;
            border: 1px solid var(--border);
            display: flex;
            flex-direction: column;
            gap: 12px;
            animation: pulse 1.5s ease-in-out infinite;
        }
        @keyframes pulse {
            0%,
            100% {
                opacity: 1;
            }
            50% {
                opacity: 0.5;
            }
        }
        .skeleton-line {
            height: 14px;
            border-radius: 7px;
            background: var(--border);
        }
        .skeleton-line.short {
            width: 60%;
        }
        .skeleton-line.medium {
            width: 80%;
        }

        /* 空状态 */
        .empty-state {
            text-align: center;
            padding: 40px;
            color: var(--text-secondary);
        }
        .empty-state .icon {
            font-size: 3rem;
            margin-bottom: 12px;
        }

        /* 回到顶部 */
        .back-to-top {
            position: fixed;
            bottom: 30px;
            right: 30px;
            width: 48px;
            height: 48px;
            border-radius: 50%;
            background: var(--primary);
            color: #fff;
            border: none;
            cursor: pointer;
            font-size: 1.2rem;
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 200;
            opacity: 0;
            transform: translateY(20px);
            transition: all var(--transition);
            pointer-events: none;
            box-shadow: 0 6px 20px rgba(59, 130, 246, 0.4);
        }
        .back-to-top.visible {
            opacity: 1;
            transform: translateY(0);
            pointer-events: auto;
        }
        .back-to-top:hover {
            transform: translateY(-4px);
            box-shadow: 0 10px 30px rgba(59, 130, 246, 0.6);
        }

        /* 响应式 */
        @media (max-width: 768px) {
            .card-grid {
                grid-template-columns: 1fr;
            }
            .header-inner {
                flex-direction: column;
                align-items: flex-start;
            }
            .category-nav {
                padding: 12px 12px 0;
                gap: 6px;
            }
            .cat-tag {
                padding: 6px 12px;
                font-size: 0.78rem;
            }
            .main-container {
                padding: 16px 12px 30px;
            }
            .logo {
                font-size: 1.2rem;
            }
        }

        /* 暗色滚动条 */
        ::-webkit-scrollbar {
            width: 8px;
        }
        ::-webkit-scrollbar-track {
            background: var(--bg);
        }
        ::-webkit-scrollbar-thumb {
            background: var(--border);
            border-radius: 4px;
        }
        ::-webkit-scrollbar-thumb:hover {
            background: #475569;
        }
    </style>
</head>
<body>
    <!-- 粒子背景 -->
    <canvas id="particles"></canvas>

    <!-- 头部 -->
    <header class="header" id="header">
        <div class="header-inner">
            <div class="logo">📡 信息聚合中心</div>
            <div class="header-actions">
                <span class="last-updated" id="lastUpdated">准备加载数据...</span>
                <button class="refresh-btn" id="refreshBtn" title="刷新所有数据">
                    <span class="icon">🔄</span> 刷新数据
                </button>
            </div>
        </div>
    </header>

    <!-- 分类导航 -->
    <nav class="category-nav" id="categoryNav">
        <button class="cat-tag active" data-cat="all">📋 全部</button>
        <button class="cat-tag" data-cat="AI/大模型" style="--cat-color: #8b5cf6;">🤖 AI/大模型</button>
        <button class="cat-tag" data-cat="科技新闻" style="--cat-color: #3b82f6;">📰 科技新闻</button>
        <button class="cat-tag" data-cat="极客/程序" style="--cat-color: #10b981;">💻 极客/程序</button>
        <button class="cat-tag" data-cat="社交媒体" style="--cat-color: #ec4899;">📱 社交媒体</button>
        <button class="cat-tag" data-cat="科技前沿" style="--cat-color: #06b6d4;">🔬 科技前沿</button>
        <button class="cat-tag" data-cat="数码评测" style="--cat-color: #f59e0b;">📷 数码评测</button>
        <button class="cat-tag" data-cat="创业/商业" style="--cat-color: #ef4444;">💼 创业/商业</button>
        <button class="cat-tag" data-cat="学习/资源" style="--cat-color: #6366f1;">📚 学习/资源</button>
    </nav>

    <!-- 主内容 -->
    <main class="main-container" id="mainContainer">
        <div class="empty-state">
            <div class="icon">⏳</div>
            <p>正在加载数据，
